  ["packing-tape", 24],
  ["shipping-labels", 100],
  ["mailer-small", 50]
])

const implementation: ReorderPolicy["Service"] = {
  minimumFor: (sku) => Effect.succeed(minimums.get(sku) ?? 10),
  reviewIntervalDays: 7
